        <div className="ag-modal-hd">
          <div className="ag-modal-ttl" style={titleColor ? { } : undefined}>
            <i className={`fa-solid ${title.icon}`} style={titleColor ? { color: titleColor } : undefined} aria-hidden="true"></i>
